<script>import Modal from '../../../components/Modal.svelte';let {onClose,onSave,busy=false}= $props();let title=$state('');let type=$state('public');let description=$state('');let error=$state('');async function submit(e){e.preventDefault();if(!title.trim()){error='Judul wajib diisi.';return;}try{await onSave({title:title.trim(),type,description:description.trim()});}catch(err){error=err.message||'Gagal membuat link tree.';}}</script>
<Modal title="Buat Link Tree" {onClose}><form onsubmit={submit} class="form-stack"><label for="tree-title">Nama link tree</label><input id="tree-title" bind:value={title} required maxlength="100" placeholder="Contoh: Tautan Kuliah"/><label for="tree-type">Privasi</label><select id="tree-type" bind:value={type}><option value="public">Public — dapat ditemukan</option><option value="unlisted">Unlisted — hanya lewat tautan</option><option value="private">Private — pribadi</option></select><label for="tree-description">Deskripsi</label><textarea id="tree-description" bind:value={description} rows="3" maxlength="500" placeholder="Ceritakan isi kumpulan tautan ini"></textarea>{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="modal-actions"><button type="button" class="btn btn-light" onclick={onClose}>Batal</button><button class="btn btn-primary" disabled={busy}>{busy?'Menyimpan…':'Buat Link Tree'}</button></div></form></Modal>
